--
-- Name: close_expired_reporting_periods(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_expired_reporting_periods() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  period public.reporting_periods;
  closed integer := 0;
  unapproved integer;
  unresolved integer;
begin
  -- The same lock as a manual open or close, and uploads wait on it, so nothing lands mid-close.
  perform pg_advisory_xact_lock(hashtext('reporting_period_status'));

  for period in
    select * from public.reporting_periods rp
    where rp.status = 'open' and public.reporting_period_past_deadline(rp)
    for update
  loop
    select
      count(*) filter (where r.approval_status::text <> 'approved'
                         and r.data_quality_state::text <> 'rejected'),
      count(*) filter (where r.validation_status::text in ('failed', 'flagged'))
    into unapproved, unresolved
    from public.esg_records r
    where r.reporting_period_id = period.id;

    update public.reporting_periods
    set status = 'closed', closed_at = now()
    where id = period.id;

    values (
      'reporting_period.closed_automatically', 'reporting_period', period.id, null,
      jsonb_build_object('status', 'open'),
      jsonb_build_object(
        'status', 'closed',
        'deadline', coalesce(period.submission_closes_on, period.end_date),
        'unapproved_records', unapproved,
        'unresolved_validation', unresolved),
      'The deadline passed.');

    select distinct uoa.user_id, 'period_closed', period.label || ' closed automatically',
           unapproved || ' record(s) still unapproved, ' || unresolved
             || ' with validation issues. No period is open, so uploads are paused until you open the next one.',
           'reporting_period', period.id, '/admin/reporting-periods'
    from public.user_org_assignments uoa
    join public.roles r on r.id = uoa.role_id and r.code = 'admin'
    join public.users u on u.id = uoa.user_id and u.is_active and u.deleted_at is null
    where uoa.revoked_at is null;

    closed := closed + 1;
  end loop;

  return closed;
end;
$$;


--
-- Name: enforce_carbon_credit_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_carbon_credit_balance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  batch_quantity numeric;
  already_used numeric;
begin
  -- Locks the batch, so two transactions against it are checked one after the other.
  select c.quantity_tco2e into batch_quantity
  from public.carbon_credits c where c.id = new.credit_id for update;
  select coalesce(sum(t.quantity_tco2e), 0) into already_used
  from public.carbon_credit_transactions t where t.credit_id = new.credit_id;
  if already_used + new.quantity_tco2e > batch_quantity + 0.0001 then
    raise exception 'This batch holds % tCO2e and % is already retired or transferred',
      batch_quantity, already_used
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_org_hierarchy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_org_hierarchy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  own_order numeric;
  parent_level text;
  parent_order numeric;
begin
  select sort_order into own_order from public.org_levels where code = new.unit_type;
  if new.parent_id is not null then
    if new.unit_type = 'group' then
      raise exception 'A group can only be the root of the organization.' using errcode = '23514';
    end if;
    select l.code, l.sort_order into parent_level, parent_order
    from public.org_units p join public.org_levels l on l.code = p.unit_type
    where p.id = new.parent_id;
    if own_order <= parent_order then
      raise exception 'A % cannot sit under a %: a child''s level must come after its parent''s.',
        new.unit_type, parent_level using errcode = '23514';
    end if;
    if exists (select 1 from public.org_unit_parents x
               where x.org_unit_id = new.id and x.parent_id = new.parent_id) then
      raise exception 'The unit already sits under that parent.' using errcode = '23514';
    end if;
  end if;

  if tg_op = 'UPDATE' and new.unit_type is distinct from old.unit_type then
    if exists (
      select 1 from public.org_units child join public.org_levels l on l.code = child.unit_type
      where l.sort_order <= own_order
        and (child.parent_id = new.id
             or child.id in (select x.org_unit_id from public.org_unit_parents x where x.parent_id = new.id))
    ) then
      raise exception 'A % cannot have a child at the same or an earlier level.', new.unit_type
        using errcode = '23514';
    end if;
    if exists (
      select 1 from public.org_unit_parents x
      join public.org_units p on p.id = x.parent_id
      join public.org_levels l on l.code = p.unit_type
      where x.org_unit_id = new.id and l.sort_order >= own_order
    ) then
      raise exception 'A % cannot sit under a parent at the same or a later level.', new.unit_type
        using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: enforce_org_unit_parent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_org_unit_parent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  main_parent uuid;
  own_level text;
  own_order numeric;
  parent_level text;
  parent_order numeric;
begin
  select o.parent_id, l.code, l.sort_order into main_parent, own_level, own_order
  from public.org_units o join public.org_levels l on l.code = o.unit_type
  where o.id = new.org_unit_id;
  if main_parent is null then
    raise exception 'A group is the top of its organization and cannot sit under another unit.'
      using errcode = '23514';
  end if;
  if new.parent_id = main_parent then
    raise exception 'The unit already sits under that parent.' using errcode = '23514';
  end if;
  select l.code, l.sort_order into parent_level, parent_order
  from public.org_units p join public.org_levels l on l.code = p.unit_type
  where p.id = new.parent_id;
  if own_order <= parent_order then
    raise exception 'A % cannot sit under a %: a child''s level must come after its parent''s.',
      own_level, parent_level using errcode = '23514';
  end if;
  if public.org_unit_root(new.org_unit_id) is distinct from public.org_unit_root(new.parent_id) then
    raise exception 'A unit can only also sit under a unit of its own group.' using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_record_document_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_record_document_org() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (select r.org_unit_id from public.esg_records r where r.id = new.esg_record_id)
     is distinct from
     (select d.org_unit_id from public.documents d where d.id = new.document_id) then
    raise exception 'A record and its evidence document must belong to the same org unit'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_super_admin_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_super_admin_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  allowed int;
  holders int;
begin
  perform pg_advisory_xact_lock(hashtext('super_admin_limit'));
  select coalesce((select (value #>> '{}')::int from public.org_settings where key = 'super_admin_limit'), 2)
    into allowed;
  select count(distinct uoa.user_id) into holders
  from public.user_org_assignments uoa
  join public.roles r on r.id = uoa.role_id and r.code = 'admin'
  join public.users u on u.id = uoa.user_id
  where uoa.revoked_at is null and u.is_active and u.deleted_at is null;
  if holders > allowed then
    raise exception 'At most % Super Admins are allowed.', allowed
      using errcode = '23514', constraint = 'super_admin_limit';
  end if;
  return null;
end;
$$;


--
-- Name: guard_org_levels(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_org_levels() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.code = 'group' then
      raise exception 'The root level cannot be removed.' using errcode = '23514';
    end if;
    return old;
  end if;
  if tg_op = 'UPDATE' and (new.code <> old.code or new.sort_order <> old.sort_order) then
    raise exception 'A level''s code and position cannot change; only its label can.' using errcode = '23514';
  end if;
  if tg_op = 'INSERT'
     and new.sort_order <= (select sort_order from public.org_levels where code = 'group') then
    raise exception 'A level cannot come before the root level.' using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: guard_user_invitation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_user_invitation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.consumed_at is not null or old.revoked_at is not null then
    raise exception 'A used or revoked invitation cannot be changed.' using errcode = '23514';
  end if;
  if new.user_id is distinct from old.user_id
     or new.token_hash is distinct from old.token_hash
     or new.expires_at is distinct from old.expires_at
     or new.created_at is distinct from old.created_at then
    raise exception 'An invitation''s account, token and expiry cannot be changed.' using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.user_org_assignments uoa
    join public.roles r on r.id = uoa.role_id
    join public.users u on u.id = uoa.user_id
    where uoa.user_id = (select auth.uid())
      and uoa.revoked_at is null
      and u.is_active
      and r.code = 'admin'
  );
$$;


--
-- Name: my_org_unit_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_org_unit_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive scoped as (
    select ou.id
    from public.org_units ou
    join public.user_org_assignments uoa on uoa.org_unit_id = ou.id
    join public.users u on u.id = uoa.user_id
    where uoa.user_id = (select auth.uid())
      and uoa.revoked_at is null
      and u.is_active
    union
    select l.child_id
    from scoped s join public.org_unit_links l on l.parent_id = s.id
  )
  select id from scoped;
$$;


--
-- Name: org_unit_root(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_unit_root(unit_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with recursive up as (
    select id, parent_id from public.org_units where id = unit_id
    union all
    select o.id, o.parent_id from public.org_units o join up on o.id = up.parent_id
  )
  select id from up where parent_id is null;
$$;


