--
-- Name: prevent_calculation_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_calculation_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and tg_table_name = 'calculations'
     and (to_jsonb(new) - 'is_current') = (to_jsonb(old) - 'is_current') then
    return new;
  end if;
  raise exception '% is append-only: % is not allowed', tg_table_name, tg_op
    using errcode = 'insufficient_privilege';
end;
$$;


