--
-- Name: prevent_referenced_factor_version_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_referenced_factor_version_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.calculations where conversion_factor_version_id = old.id
  ) then
    if new.value <> old.value
      or new.input_unit <> old.input_unit
      or new.output_unit <> old.output_unit then
      raise exception 'Cannot mutate a conversion_factor_version already referenced by a calculation — create a new version instead';
    end if;
  end if;
  return new;
end;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: reporting_periods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reporting_periods (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    label text NOT NULL,
    period_type public.reporting_period_type DEFAULT 'monthly'::public.reporting_period_type NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    status public.reporting_period_status DEFAULT 'draft'::public.reporting_period_status NOT NULL,
    opened_at timestamp with time zone,
    closed_at timestamp with time zone,
    submission_opens_on date,
    submission_closes_on date,
    CONSTRAINT reporting_periods_dates_check CHECK ((end_date > start_date)),
    CONSTRAINT reporting_periods_submission_window_check CHECK (((submission_opens_on IS NULL) OR (submission_closes_on IS NULL) OR (submission_closes_on >= submission_opens_on)))
);


--
-- Name: reporting_period_past_deadline(public.reporting_periods); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reporting_period_past_deadline(p public.reporting_periods) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(p.submission_closes_on, p.end_date) < (now() at time zone 'Asia/Kolkata')::date;
$$;


--
-- Name: require_record_document(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_record_document() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.verification_status = 'user_verified' and old.verification_status <> 'user_verified'
     and not exists (select 1 from public.esg_record_documents d where d.esg_record_id = new.id) then
    raise exception 'A record cannot be verified without an evidence document'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: session_limits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.session_limits(OUT idle_minutes integer, OUT absolute_minutes integer) RETURNS record
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  setting jsonb;
begin
  select value into setting from public.org_settings where key = 'session_limits';
  begin
    idle_minutes := (setting ->> 'idle_minutes')::int;
    absolute_minutes := (setting ->> 'absolute_minutes')::int;
  exception when others then
    idle_minutes := null;
    absolute_minutes := null;
  end;
  if idle_minutes is null or idle_minutes < 1 or idle_minutes > 1440 then
    idle_minutes := 180;
  end if;
  if absolute_minutes is null or absolute_minutes < idle_minutes or absolute_minutes > 10080 then
    absolute_minutes := greatest(720, idle_minutes);
  end if;
end;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: touch_session(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_session(p_session_id uuid, p_user_id uuid, p_activity boolean) RETURNS TABLE(state text, idle_expires_at timestamp with time zone, absolute_expires_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  lim record;
  s public.user_sessions;
  moment timestamptz := clock_timestamp();
begin
  select * into lim from public.session_limits();

  values (p_session_id, p_user_id, moment, moment)
  on conflict (session_id) do nothing;

  select * into s from public.user_sessions where session_id = p_session_id for update;

  -- A session id can only ever belong to the person it started with.
  if s.user_id <> p_user_id or s.ended_at is not null then
    return query select 'expired'::text, null::timestamptz, null::timestamptz;
    return;
  end if;

  if moment >= s.started_at + make_interval(mins => lim.absolute_minutes) then
    update public.user_sessions set ended_at = moment, ended_reason = 'absolute'
    where session_id = p_session_id;
    return query select 'expired'::text, null::timestamptz, null::timestamptz;
    return;
  end if;

  if moment >= s.last_activity_at + make_interval(mins => lim.idle_minutes) then
    update public.user_sessions set ended_at = moment, ended_reason = 'idle'
    where session_id = p_session_id;
    return query select 'expired'::text, null::timestamptz, null::timestamptz;
    return;
  end if;

  if p_activity then
    update public.user_sessions set last_activity_at = moment where session_id = p_session_id;
    s.last_activity_at := moment;
  end if;

  return query select
    'active'::text,
    s.last_activity_at + make_interval(mins => lim.idle_minutes),
    s.started_at + make_interval(mins => lim.absolute_minutes);
end;
$$;


