--
-- Name: org_unit_links; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.org_unit_links WITH (security_invoker='true') AS
 SELECT org_units.id AS child_id,
    org_units.parent_id,
    true AS is_main
   FROM public.org_units
  WHERE (org_units.parent_id IS NOT NULL)
UNION ALL
 SELECT org_unit_parents.org_unit_id AS child_id,
    org_unit_parents.parent_id,
    false AS is_main
   FROM public.org_unit_parents;


--
-- Name: org_unit_tree; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.org_unit_tree WITH (security_invoker='true') AS
 WITH RECURSIVE tree AS (
         SELECT org_units.id AS ancestor_id,
            org_units.id AS descendant_id,
            0 AS depth
           FROM public.org_units
        UNION
         SELECT t.ancestor_id,
            l.child_id,
            (t.depth + 1)
           FROM (tree t
             JOIN public.org_unit_links l ON ((l.parent_id = t.descendant_id)))
        )
 SELECT ancestor_id,
    descendant_id,
    min(depth) AS depth
   FROM tree
  GROUP BY ancestor_id, descendant_id;


--
-- Name: consolidation_records; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.consolidation_records WITH (security_invoker='true') AS
 SELECT t.ancestor_id AS org_unit_id,
    r.id AS esg_record_id,
    r.org_unit_id AS source_org_unit_id,
    r.reporting_period_id,
    r.metric_id,
    m.scope_id,
    r.approval_status,
    c.id AS calculation_id,
        CASE
            WHEN m.requires_calculation THEN c.result_value
            ELSE r.activity_value_verified
        END AS value,
        CASE
            WHEN m.requires_calculation THEN c.result_unit
            ELSE r.activity_unit
        END AS value_unit,
    (m.requires_calculation AND (c.id IS NULL)) AS not_calculated
   FROM (((public.esg_records r
     JOIN public.esg_metrics m ON ((m.id = r.metric_id)))
     JOIN public.org_unit_tree t ON ((t.descendant_id = r.org_unit_id)))
     LEFT JOIN public.calculations c ON (((c.esg_record_id = r.id) AND c.is_current)))
  WHERE ((r.verification_status = 'user_verified'::public.record_verification_status) AND (r.data_quality_state <> 'rejected'::public.data_quality_state));


