    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: rate_limit_events_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.rate_limit_events ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.rate_limit_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: report_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.report_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    requested_by uuid NOT NULL,
    org_unit_id uuid NOT NULL,
    reporting_period_id uuid,
    report_type public.report_type NOT NULL,
    status public.report_run_status DEFAULT 'pending'::public.report_run_status NOT NULL,
    storage_path text,
    snapshot_data jsonb,
    error_message text,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    financial_year integer,
    period_from date,
    period_to date,
    CONSTRAINT report_runs_one_coverage CHECK ((((period_from IS NULL) = (period_to IS NULL)) AND ((period_from IS NULL) OR (period_from <= period_to)) AND (num_nonnulls(reporting_period_id, financial_year, period_from) = 1)))
);


--
-- Name: role_permissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.role_permissions (
    role_id uuid NOT NULL,
    permission_id uuid NOT NULL
);


--
-- Name: roles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.roles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    is_system_role boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    uploads_for_role_id uuid,
    CONSTRAINT roles_uploads_for_not_self CHECK ((uploads_for_role_id IS DISTINCT FROM id))
);


--
-- Name: COLUMN roles.uploads_for_role_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.roles.uploads_for_role_id IS 'People holding this role may upload into the categories owned by that role, at the org units they are assigned to.';


--
-- Name: scopes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.scopes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    parent_scope_id uuid,
    name text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL
);


--
-- Name: submission_expectations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.submission_expectations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_unit_id uuid NOT NULL,
    metric_id uuid NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid NOT NULL,
    display_name text NOT NULL,
    email text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    theme text DEFAULT 'theme-2'::text NOT NULL,
    employee_id text,
    notifications_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT users_theme_check CHECK ((theme = ANY (ARRAY['theme-1'::text, 'theme-2'::text, 'theme-3'::text])))
);


--
-- Name: user_display_names; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_display_names AS
 SELECT id,
    display_name
   FROM public.users;


--
-- Name: user_invitations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_invitations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    token_hash text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    revoked_at timestamp with time zone,
    CONSTRAINT user_invitations_one_ending CHECK (((consumed_at IS NULL) OR (revoked_at IS NULL))),
    CONSTRAINT user_invitations_token_hash_check CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: user_org_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_org_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    org_unit_id uuid NOT NULL,
    role_id uuid NOT NULL,
    assigned_by uuid NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone
);


--
-- Name: user_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_sessions (
    session_id uuid NOT NULL,
    user_id uuid NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    last_activity_at timestamp with time zone DEFAULT now() NOT NULL,
    ended_at timestamp with time zone,
    ended_reason text,
    CONSTRAINT user_sessions_ended_reason_check CHECK ((ended_reason = ANY (ARRAY['idle'::text, 'absolute'::text, 'signed_out'::text]))),
    CONSTRAINT user_sessions_ended_with_reason CHECK (((ended_at IS NULL) = (ended_reason IS NULL)))
);


--
-- Name: validation_results; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.validation_results (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    esg_record_id uuid NOT NULL,
    validation_rule_id uuid,
    rule_type public.validation_rule_type NOT NULL,
    result public.validation_result NOT NULL,
    message text,
    evaluated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: validation_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.validation_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    metric_id uuid,
    rule_type public.validation_rule_type NOT NULL,
    rule_definition jsonb NOT NULL,
    severity public.validation_severity DEFAULT 'hard_fail'::public.validation_severity NOT NULL,
    description text,
    is_active boolean DEFAULT true NOT NULL
);


--
-- Name: verifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    esg_record_id uuid NOT NULL,
    ocr_extraction_id uuid,
    verified_by uuid NOT NULL,
    verified_at timestamp with time zone DEFAULT now() NOT NULL,
    is_manual_exception boolean DEFAULT false NOT NULL,
    notes text
);


