--
-- Start from no privileges on the restored objects; the ACL statements below then restore exactly the source's.
-- (A fresh Supabase database grants the browser roles rights on every new object by default.)
--
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC, anon, authenticated, service_role, chat_reader;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM PUBLIC, anon, authenticated, service_role, chat_reader;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM anon, authenticated, service_role, chat_reader;

--
-- Name: SCHEMA public; Type: ACL; Schema: -; Owner: -
--

GRANT USAGE ON SCHEMA public TO postgres;
GRANT USAGE ON SCHEMA public TO anon;
GRANT USAGE ON SCHEMA public TO authenticated;
GRANT USAGE ON SCHEMA public TO service_role;
GRANT USAGE ON SCHEMA public TO chat_reader;


--
-- Name: FUNCTION close_expired_reporting_periods(); Type: ACL; Schema: public; Owner: -
--

REVOKE ALL ON FUNCTION public.close_expired_reporting_periods() FROM PUBLIC;
